#!/bin/bash
# Compares the public API of this repository's crates as generated by x23c
# and as generated by xdrc, and prints any difference. Run by hand, from
# anywhere in the repository, before moving to a new xdrc or x23c; CI does
# not run it.
#
#   scripts/compare-xdrc-api.sh [--x23c PATH] [--xdrc PATH] [--keep]
#                               [--docs] [--attrs]
#
# --x23c  the x23c to compare with; by default the latest-x23c release of
#         thruputchain/hogd, as generate.sh used before xdrc
# --xdrc  the xdrc to compare; by default the one pinned in xdrc.sh
# --keep  keep the work directory, which holds both generated trees, their
#         rustdoc JSON and the API summaries
# --docs  also compare doc comments
# --attrs also compare the attributes rustdoc records, such as `repr`,
#         `non_exhaustive`, `allow` and evaluated `cfg_attr`s
#
# With --docs the summaries are expected to differ in one way: xdrc attaches a
# union's doc comment to the union rather than to an inline type of one of its
# arms. This currently produces the movement of one comment about `AuthClaim`.
#
# Each compiler generates the sources from this checkout's protocol/ into its
# own copy of the repository. rustdoc then describes every crate with
# generated code as JSON (which needs the nightly toolchain below), and
# api_summary.py reduces that to one line per public item: field types,
# variants and discriminants, constant values, trait impls and signatures.
# Exits 0 if the summaries are identical, 1 if they differ.

set -euo pipefail

readonly NIGHTLY_TOOLCHAIN="nightly-2026-05-26"

# The crates with generated code.
readonly CRATES=(
  thruput-xdr
  thruput-trace
  thruput-scp
  thruput-rpc
  thruput-node-types
  thruput-coordinator
  thruput-node-rpc
  thruput-indexer
  thruput-db-gateway
  thruput-view
  thruput-spec
)

x23c=
xdrc=
keep=false
summary_flags=()
while [[ $# -gt 0 ]]; do
  case $1 in
    --x23c) x23c=${2:?--x23c needs a path}; shift ;;
    --xdrc) xdrc=${2:?--xdrc needs a path}; shift ;;
    --keep) keep=true ;;
    --docs) summary_flags+=(--docs) ;;
    --attrs) summary_flags+=(--attrs) ;;
    *) sed -n '2,23s/^# \{0,1\}//p' "$0" >&2; exit 2 ;;
  esac
  shift
done

cd "$(git rev-parse --show-toplevel)"
scripts=$PWD/scripts

work=$(mktemp -d)
if $keep; then
  echo "-- Work directory: ${work} --" >&2
else
  trap 'rm -rf "$work"' EXIT
fi

if [[ -z $x23c ]]; then
  os=$(uname -s | tr '[:upper:]' '[:lower:]')
  [[ $os == darwin ]] && os=macos
  asset="x23c-${os}-$(uname -m).tar.gz"
  echo "-- Downloading ${asset} from thruputchain/hogd latest-x23c release --" >&2
  # Unpacked apart from the generated trees, one of which is named x23c.
  release=${work}/x23c-release
  mkdir "$release"
  curl -fsSL --retry 3 -o "${release}/${asset}" \
    "https://github.com/thruputchain/hogd/releases/download/latest-x23c/${asset}"
  tar xzf "${release}/${asset}" -C "$release"
  x23c=${release}/x23c
fi
if [[ -z $xdrc ]]; then
  source "${scripts}/xdrc.sh"
  xdrc=$(xdrc_install)
fi

if ! rustup run "$NIGHTLY_TOOLCHAIN" rustdoc --version >/dev/null 2>&1; then
  rustup toolchain install "$NIGHTLY_TOOLCHAIN" --profile minimal >&2
fi

for compiler in x23c xdrc; do
  bin=${!compiler}
  tree=${work}/${compiler}
  echo "-- Generating with ${compiler} (${bin}) --" >&2
  mkdir "$tree"
  tar --exclude=./target --exclude=.git -cf - . | tar -xf - -C "$tree"
  if ! XDRC=$bin "${scripts}/generate.sh" --out "$tree" >"${work}/${compiler}-generate.log" 2>&1; then
    cat "${work}/${compiler}-generate.log" >&2
    exit 2
  fi

  echo "-- Describing the API generated by ${compiler} --" >&2
  mkdir "${work}/${compiler}-api"
  for crate in "${CRATES[@]}"; do
    RUSTDOCFLAGS="-Z unstable-options --output-format json" \
      CARGO_TARGET_DIR="${work}/${compiler}-target" \
      cargo +"$NIGHTLY_TOOLCHAIN" doc --quiet --locked --no-deps --all-features \
        --manifest-path "${tree}/Cargo.toml" -p "$crate"
    json=${work}/${compiler}-target/doc/${crate//-/_}.json
    python3 "${scripts}/api_summary.py" "${summary_flags[@]}" "$json" \
      >"${work}/${compiler}-api/${crate}.txt"
  done
done

if diff -r "${work}/x23c-api" "${work}/xdrc-api"; then
  echo "-- The public APIs are identical: $(cat "${work}"/xdrc-api/*.txt | wc -l) lines --" >&2
else
  echo "-- The public APIs differ; see the diff above --" >&2
  exit 1
fi
